"""Nederlands — profeten (prophets_001 … prophets_150)."""

T = {
"prophets_001": ("Welke profeet bouwde de ark in opdracht van Allah?", ["Nuh (Noach)", "Ibrahim (Abraham)", "Musa (Mozes)", "Yusuf (Jozef)"], "Allah gebood Nuh de ark te bouwen om de gelovigen van de zondvloed te redden."),
"prophets_002": ("Welke profeet werd in een vuur geworpen dat Allah koel en veilig voor hem maakte?", ["Ibrahim (Abraham)", "Nuh (Noach)", "Dawud (David)", "Ayyub (Job)"], "Allah gebood het vuur koel en veilig te zijn voor Ibrahim."),
"prophets_003": ("Welke profeet werd door een enorme vis opgeslokt?", ["Yunus (Jona)", "Ilyas (Elia)", "Idris (Henoch)", "Zakariyya (Zacharias)"], "Yunus werd door de vis opgeslokt nadat hij zijn volk in woede had verlaten; Allah vergaf hem."),
"prophets_004": ("Welke profeet legde de droom van de koning uit over zeven vette en zeven magere koeien?", ["Yusuf (Jozef)", "Ya'qub (Jakob)", "Isma'il (Ismaël)", "Ishaq (Isaak)"], "Yusuf legde de droom van de koning uit en voorspelde zeven jaren van overvloed gevolgd door zeven jaren van hongersnood."),
"prophets_005": ("Tot welke profeet sprak Allah volgens de Koran rechtstreeks?", ["Musa (Mozes)", "Harun (Aäron)", "Yusuf (Jozef)", "Sulaiman (Salomo)"], "De Koran zegt dat Allah rechtstreeks tot Musa sprak."),
"prophets_006": ("Welke profeet verstond de taal van de vogels?", ["Sulaiman (Salomo)", "Dawud (David)", "Yunus (Jona)", "Yusuf (Jozef)"], "Allah leerde Sulaiman de taal van de vogels."),
"prophets_007": ("Aan welke profeet werd het geschrift gegeven dat de Zabur (Psalmen) heet?", ["Dawud (David)", "Musa (Mozes)", "Isa (Jezus)", "Ibrahim (Abraham)"], "De Koran vermeldt dat de Zabur aan Dawud werd gegeven."),
"prophets_008": ("Welke profeet werd zonder vader geboren, door Allahs woord «Wees, en het is»?", ["Isa (Jezus)", "Yahya (Johannes)", "Isma'il (Ismaël)", "Ishaq (Isaak)"], "De Koran beschrijft de wonderbaarlijke geboorte van Isa zonder vader, door Allahs woord alleen."),
"prophets_009": ("Welk hoofdstuk (soera) van de Koran is genoemd naar de moeder van een profeet?", ["Maryam", "Yusuf", "Nuh", "Hud"], "Soera 19, Maryam, is genoemd naar de moeder van de profeet Isa."),
"prophets_010": ("Welke profeet werd beproefd met een ernstige ziekte en wordt geprezen om zijn geduld?", ["Ayyub (Job)", "Zakariyya (Zacharias)", "Yahya (Johannes)", "Idris (Henoch)"], "Ayyub bleef geduldig tijdens een zeer zware beproeving, en Allah beloonde hem."),
"prophets_011": ("Voor wie gebood Allah de engelen zich neer te werpen, als teken van eer?", ["Adam", "Nuh (Noach)", "Ibrahim (Abraham)", "Musa (Mozes)"], "Allah gebood de engelen zich voor Adam neer te werpen als teken van eer, niet van aanbidding."),
"prophets_012": ("Welke profeet wordt «Khalilullah» genoemd, de boezemvriend van Allah?", ["Ibrahim (Abraham)", "Musa (Mozes)", "Isa (Jezus)", "Muhammad ﷺ"], "De Koran beschrijft Ibrahim als de boezemvriend (khalil) van Allah."),
"prophets_013": ("Welke profeet werd door zijn broers in een put gegooid?", ["Yusuf (Jozef)", "Bunyamin (Benjamin)", "Ya'qub (Jakob)", "Isma'il (Ismaël)"], "De broers van Yusuf gooiden hem uit jaloezie in een put."),
"prophets_014": ("Wiens volk werd door een zondvloed vernietigd nadat het hem had verworpen?", ["Nuh (Noach)", "Hud", "Salih", "Shu'ayb"], "Het volk van Nuh werd door de zondvloed verzwolgen nadat het zijn boodschap hardnekkig had verworpen."),
"prophets_015": ("Welke profeet zag de zee splijten om zijn volk van de Farao te redden?", ["Musa (Mozes)", "Harun (Aäron)", "Yusuf (Jozef)", "Isma'il (Ismaël)"], "Allah gebood Musa op de zee te slaan, en zij spleet zodat de gelovigen konden oversteken."),
"prophets_016": ("Welke profeet oordeelde samen met zijn vader Dawud over een akker die door schapen was afgegraasd?", ["Sulaiman (Salomo)", "Isma'il (Ismaël)", "Yusuf (Jozef)", "Ishaq (Isaak)"], "De Koran vertelt dat Sulaiman en Dawud over deze zaak oordeelden, en Allah gaf Sulaiman het inzicht erin."),
"prophets_017": ("Wiens moeder kreeg de opdracht haar baby in een rivier te leggen?", ["Musa (Mozes)", "Isa (Jezus)", "Yusuf (Jozef)", "Isma'il (Ismaël)"], "Allah inspireerde de moeder van Musa om hem in een kist op de rivier te leggen om hem te beschermen."),
"prophets_018": ("Wiens kameelmerrie was een teken voor zijn volk, de Thamud?", ["Salih", "Hud", "Shu'ayb", "Lut (Lot)"], "Allah zond een kameelmerrie als teken aan het volk van de Thamud via de profeet Salih."),
"prophets_019": ("Aan welke profeet leerde Allah de namen van alle dingen?", ["Adam", "Nuh (Noach)", "Ibrahim (Abraham)", "Musa (Mozes)"], "Allah leerde Adam de namen van alle dingen, en de engelen erkenden Allahs wijsheid."),
"prophets_020": ("Welke profeet sprak tot de mensen toen hij nog een baby in de wieg was?", ["Isa (Jezus)", "Yahya (Johannes)", "Yusuf (Jozef)", "Ismail (Ismaël)"], "De baby Isa sprak vanuit de wieg: «Ik ben de dienaar van Allah; Hij heeft mij het Boek gegeven.»"),
"prophets_021": ("Met welke zoon legde Ibrahim de fundamenten van de Ka'ba?", ["Ismail (Ismaël)", "Ishaq (Isaak)", "Yaqub (Jakob)", "Yusuf (Jozef)"], "«En toen Ibrahim en Ismail de fundamenten van het Huis optrokken…»: zij bouwden samen."),
"prophets_022": ("Welke zoon werd aan de profeet Zakariyya op hoge leeftijd aangekondigd?", ["Yahya (Johannes)", "Isa (Jezus)", "Ismail (Ismaël)", "Ishaq (Isaak)"], "«O Zakariyya, Wij brengen jou het goede nieuws van een jongen wiens naam Yahya zal zijn.»"),
"prophets_023": ("Waarin veranderde de staf van Musa toen Allah hem zei die neer te werpen?", ["In een bewegende slang", "In een vogel", "In een waterbron", "In een licht"], "«Werp hem neer, o Musa!» Hij wierp hem, en hij werd een slang die snel bewoog."),
"prophets_024": ("Wat zag de jonge Yusuf in zijn droom voor zich buigen?", ["Elf sterren, de zon en de maan", "Zeven vette koeien", "Een regen van goud", "Een tuin van palmen"], "Yusuf zag elf sterren en de zon en de maan zich voor hem neerwerpen: een teken van zijn bestemming."),
"prophets_025": ("Naar welk volk werd de profeet Hud gezonden?", ["De 'Ad", "De Thamud", "Het volk van Madyan", "Het volk van de Farao"], "«En tot de 'Ad, hun broeder Hud…»: hij riep hen op om Allah alleen te aanbidden."),
"prophets_026": ("Naar welk volk werd de profeet Shu'ayb gezonden?", ["Het volk van Madyan", "De 'Ad", "De Thamud", "Het volk van Nuh"], "«En tot Madyan, hun broeder Shu'ayb…»: hij gebood hen eerlijke maat en gewicht te geven."),
"prophets_027": ("Welke profeet wordt in de Koran «Dhun-Nun» (de man van de vis) genoemd?", ["Yunus (Jona)", "Musa (Mozes)", "Sulayman (Salomo)", "Ayyub (Job)"], "«En Dhun-Nun, toen hij in woede wegging…»: dit is Yunus, later door de vis opgeslokt."),
"prophets_028": ("In welke soera reist Musa om te leren van een dienaar aan wie Allah bijzondere kennis gaf?", ["Al-Kahf (De Grot)", "Yusuf", "Maryam", "An-Naml"], "In soera Al-Kahf vergezelt Musa een wijze dienaar en leert hij geduld met wat hij nog niet begrijpt."),
"prophets_029": ("Welke profeet wordt het vaakst bij naam genoemd in de Koran?", ["Musa (Mozes)", "Ibrahim (Abraham)", "Nuh (Noach)", "Isa (Jezus)"], "Musa is de vaakst genoemde profeet in de Koran; zijn verhaal met de Farao keert vele malen terug."),
"prophets_030": ("Hoeveel profeten worden bij naam genoemd in de Koran?", ["25", "10", "50", "99"], "Vijfentwintig profeten worden in de Koran bij naam genoemd, van Adam tot Muhammad ﷺ."),
"prophets_031": ("Welke profeet genas met Allahs toestemming de blinde en de melaatse?", ["Isa (Jezus)", "Musa (Mozes)", "Dawud (David)", "Yunus (Jona)"], "Isa genas de blinde en de melaatse met Allahs toestemming: een teken voor zijn volk."),
"prophets_032": ("Hoe lang bleef Nuh volgens de Koran onder zijn volk om hen tot Allah op te roepen?", ["950 jaar", "100 jaar", "300 jaar", "40 jaar"], "«Hij verbleef onder hen duizend jaar min vijftig»: 950 jaar van geduldig oproepen."),
"prophets_033": ("Waaruit schiep Allah Adam volgens de Koran?", ["Uit klei", "Uit licht", "Uit vuur", "Uit water"], "Allah zei tegen de engelen: «Ik ga een mens scheppen uit klei.»"),
"prophets_034": ("Wie verleidde Adam en zijn vrouw om van de verboden boom te eten?", ["Shaytan (Iblis)", "Een engel", "Een vogel", "Een koning"], "Shaytan fluisterde hen in zodat zij van de boom zouden eten die Allah had verboden."),
"prophets_035": ("Welke reden gaf Iblis om te weigeren zich voor Adam neer te werpen?", ["«Ik ben beter dan hij: U schiep mij uit vuur en hem uit klei»", "Hij wist niet wie Adam was", "Hij was bang voor de engelen", "Hij sliep"], "Iblis weigerde uit hoogmoed: «U schiep mij uit vuur, en hem schiep U uit klei.»"),
"prophets_036": ("Welk dier zond Allah na de doodslag tussen de twee zonen van Adam om te tonen hoe het lichaam begraven moest worden?", ["Een raaf", "Een hond", "Een duif", "Een vos"], "Allah zond een raaf die in de grond krabde om de moordenaar te tonen hoe hij het lichaam van zijn broer kon verbergen."),
"prophets_037": ("Wat zegt de Koran over de profeet Idris?", ["Allah verhief hem tot een hoge rang", "Hij bouwde een ark", "Hij werd door een vis opgeslokt", "Hij sprak met de mieren"], "«En Wij verhieven hem tot een hoge rang.»"),
"prophets_038": ("Wat deed de zoon van Nuh toen zijn vader hem in de ark riep?", ["Hij weigerde en zei dat hij op een berg zou schuilen", "Hij ging als eerste aan boord", "Hij bouwde zijn eigen ark", "Hij ging dieren verzamelen"], "Hij zei: «Ik zal mijn toevlucht zoeken op een berg»; de golven overspoelden hem."),
"prophets_039": ("Op welke berg kwam de ark van Nuh volgens de Koran tot rust?", ["De berg Judi", "De berg Sinaï", "De berg Uhud", "De berg Arafat"], "«En de ark kwam tot rust op al-Judi.»"),
"prophets_040": ("Wat gebood Allah Nuh in de ark te laden?", ["Een paar van elke soort, en de gelovigen", "Alleen zijn familie", "Alleen vogels", "Goud en zilver"], "«Laad erin een paar van elke soort, en jouw familie… en wie gelooft.»"),
"prophets_041": ("Wat deden de leiders van het volk van Nuh toen zij hem de ark zagen bouwen?", ["Zij bespotten hem", "Zij hielpen hem", "Zij brachten hem hout", "Zij baden met hem"], "Telkens wanneer leiders van zijn volk voorbijkwamen, bespotten zij hem."),
"prophets_042": ("Hoe beschrijft de Koran Nuh in soera Al-Isra?", ["Een dankbare dienaar", "Een machtige koning", "Een grote reiziger", "Een zwijgzame man"], "«Voorwaar, hij was een dankbare dienaar.»"),
"prophets_043": ("Hoe werden de 'Ad, naar wie Hud was gezonden, vernietigd?", ["Door een gewelddadige, razende wind", "Door een zondvloed", "Door een regen van stenen", "Door een aardbeving"], "«Wat de 'Ad betreft, zij werden vernietigd door een gierende, gewelddadige wind.»"),
"prophets_044": ("Wat trof de Thamud, het volk van Salih?", ["Een vreselijke schreeuw", "Een zondvloed", "Een hongersnood", "Een zwerm sprinkhanen"], "«En de schreeuw greep degenen die onrecht hadden gedaan.»"),
"prophets_045": ("Wat is de naam van de vader van Ibrahim die in de Koran wordt genoemd?", ["Azar", "Tarih", "Lut", "Kan'an"], "«Ibrahim zei tegen zijn vader Azar: neem jij afgoden als goden?»"),
"prophets_046": ("Welk beeld liet Ibrahim heel nadat hij de afgoden had stukgeslagen?", ["Het grootste", "Het kleinste", "Het gouden", "Geen enkel, hij brak ze allemaal"], "Hij sloeg ze aan stukken, behalve het grootste, opdat zijn volk het zou ondervragen."),
"prophets_047": ("Wat verklaarde Ibrahim nadat hij de ster, de maan en daarna de zon had zien ondergaan?", ["«Ik houd niet van wat ondergaat»", "«De zon is mijn heer»", "«De maan is het mooist»", "«Ik ga slapen»"], "Telkens als er een onderging zei hij: «Ik houd niet van wat ondergaat», en hij wendde zich tot de Schepper."),
"prophets_048": ("Hoeveel vogels zei Allah Ibrahim te nemen, om hem te tonen hoe Hij de doden tot leven wekt?", ["Vier", "Twee", "Zeven", "Twaalf"], "«Neem vier vogels… roep ze dan: zij zullen haastig naar je toe komen.»"),
"prophets_049": ("Wat diende Ibrahim zijn gasten op, de engelen die met goed nieuws kwamen?", ["Een gebraden kalf", "Dadels", "Melk", "Brood en honing"], "«Hij talmde niet om een gebraden kalf te brengen.»"),
"prophets_050": ("Welk goed nieuws brachten de engelen aan de vrouw van Ibrahim?", ["De geboorte van Ishaq", "Een reis", "Grote rijkdom", "Overvloedige regen"], "«Wij brachten haar het goede nieuws van Ishaq, en na Ishaq, Ya'qub.»"),
"prophets_051": ("Hoe reageerde de zoon van Ibrahim toen zijn vader hem de droom vertelde dat hij hem moest offeren?", ["Hij aanvaardde het: «Doe wat jou is bevolen»", "Hij vluchtte", "Hij huilde en weigerde", "Hij verstopte zich"], "Hij zei: «O mijn vader, doe wat jou is bevolen.» En Allah loste hem af met een groot offer."),
"prophets_052": ("Waar zegt Ibrahim in zijn gebed dat hij een deel van zijn familie heeft gevestigd?", ["In een vallei zonder gewassen, bij het Heilige Huis", "Aan de Nijl", "In een bos", "Op een eiland"], "«Ik heb een deel van mijn nageslacht gevestigd in een onbebouwde vallei bij Uw Heilige Huis.»"),
"prophets_053": ("Wat vroeg Ibrahim in zijn gebed voor de stad Mekka?", ["Dat zij een veilige stad zou zijn en dat haar bewoners vruchten zouden krijgen", "Dat zij een koninkrijk zou worden", "Dat het er altijd zou regenen", "Dat zij een rivier zou hebben"], "«Mijn Heer, maak dit een veilige stad en voorzie haar bewoners van vruchten.»"),
"prophets_054": ("Terwijl zij de Ka'ba optrokken, vroegen Ibrahim en Isma'il Allah om onder hun nageslacht te zenden…?", ["Een boodschapper uit hun midden, die Zijn verzen voordraagt", "Een koning", "Een leger", "Een schat"], "«Onze Heer, zend onder hen een boodschapper uit hun midden die hun Uw verzen zal voordragen.»"),
"prophets_055": ("De Koran zegt dat één profeet in zijn eentje «een gemeenschap (umma)» was. Welke?", ["Ibrahim", "Nuh", "Musa", "Sulayman"], "«Voorwaar, Ibrahim was een gemeenschap, vroom gehoorzaam aan Allah, oprecht.»"),
"prophets_056": ("Om welke eigenschap prijst de Koran Isma'il in soera Maryam?", ["Hij was trouw aan zijn belofte", "Hij was zeer rijk", "Hij was een koning", "Hij kon zwemmen"], "«Voorwaar, hij was trouw aan zijn belofte, en hij was een boodschapper en een profeet.»"),
"prophets_057": ("Welke straf trof het volk van Lut?", ["Een regen van stenen van gebakken klei", "Een zondvloed", "Een zwerm insecten", "Een droogte"], "«Wij keerden de stad ondersteboven en lieten er stenen van gebakken klei op regenen.»"),
"prophets_058": ("De vrouwen van welke twee profeten geeft de Koran als voorbeeld van ongeloof?", ["Nuh en Lut", "Ibrahim en Musa", "Dawud en Sulayman", "Ayyub en Yunus"], "«Allah geeft als voorbeeld voor de ongelovigen: de vrouw van Nuh en de vrouw van Lut.»"),
"prophets_059": ("Wie was de vader van Ya'qub?", ["Ishaq", "Isma'il", "Ibrahim", "Yusuf"], "De engelen kondigden de vrouw van Ibrahim aan: «Ishaq, en na Ishaq, Ya'qub»."),
"prophets_060": ("Wat gebeurde er met het gezichtsvermogen van Ya'qub door het wenen om Yusuf?", ["Zijn ogen werden wit", "Hij zag beter 's nachts", "Er veranderde niets", "Hij verloor een oog"], "«Zijn ogen werden wit van verdriet, en hij hield het in.»"),
"prophets_061": ("Wat gaf Ya'qub zijn gezichtsvermogen terug?", ["Het hemd van Yusuf, over zijn gezicht geworpen", "Een plant", "Zamzam-water", "Een zalf"], "Yusuf zei: «Werp mijn hemd over het gezicht van mijn vader; hij zal weer zien.»"),
"prophets_062": ("Wat verkoos Yusuf boven toegeven aan datgene waartoe hij ten onrechte werd uitgenodigd?", ["De gevangenis", "De ballingschap", "Rijkdom", "Stilte"], "«Mijn Heer, de gevangenis is mij liever dan datgene waartoe zij mij uitnodigen.»"),
"prophets_063": ("In de gevangenis vertelden twee jonge mannen Yusuf hun dromen. Wat zag een van hen?", ["Hij perste druiven", "Hij vloog", "Hij hoedde schapen", "Hij groef een put"], "De een zag zichzelf wijn persen, de ander brood op zijn hoofd dragen waarvan de vogels aten."),
"prophets_064": ("Hoeveel jaren van overvloed en daarna van droogte voorspelde Yusuf aan de koning?", ["Zeven en zeven", "Drie en drie", "Tien en tien", "Eén en één"], "«Jullie zullen zeven jaar zaaien… dan komen er zeven moeilijke jaren.»"),
"prophets_065": ("Welk ambt vroeg Yusuf aan de koning van Egypte?", ["De voorraadschuren van het land", "Het bevel over het leger", "De troon", "De goudschat"], "«Stel mij aan over de voorraadschuren van het land: ik ben een kundige bewaarder.»"),
"prophets_066": ("Wat liet Yusuf in de bagage van zijn jongere broer leggen om hem bij zich te houden?", ["De drinkbeker van de koning", "Een zak goud", "Een brief", "Zijn hemd"], "«Hij legde de drinkbeker in de zak van zijn broer.»"),
"prophets_067": ("Welk advies gaf Ya'qub zijn zonen voordat zij Egypte binnengingen?", ["Ga door verschillende poorten naar binnen", "Reis 's nachts", "Vermom jezelf", "Neem geschenken mee"], "«Ga niet door één poort naar binnen, maar door verschillende poorten.»"),
"prophets_068": ("Waarom kwamen de broers van Yusuf naar Egypte toen hij daar de leiding had?", ["Om voorraden te halen tijdens de hongersnood", "Om hem te vinden", "Voor een bedevaart", "Om kamelen te verkopen"], "Zijn broers kwamen voor graan; zij kwamen bij hem binnen en herkenden hem niet."),
"prophets_069": ("In welk huis werd de baby Musa opgenomen nadat hij in de rivier was gelegd?", ["Dat van de Farao", "Dat van een herder", "Dat van een visser", "Dat van een koopman"], "Het huishouden van de Farao nam hem op, opdat hij op een dag een vijand en een verdriet voor hen zou zijn."),
"prophets_070": ("Hoe keerde de baby Musa uiteindelijk terug naar zijn moeder?", ["Hij weigerde elke voedster, en zijn zus stelde zijn moeder voor", "De Farao gaf hem uit medelijden terug", "Zijn moeder stal hem 's nachts", "Een engel droeg hem"], "Allah liet hem de voedsters weigeren; zijn zus stelde een gezin voor: het was zijn moeder, die hem voedde."),
"prophets_071": ("Waarom moest Musa Egypte haastig verlaten, vóór zijn missie?", ["Hij had onbedoeld een man gedood met een klap", "Hij had uit het paleis gestolen", "Hij weigerde belasting te betalen", "Hij had de Farao beledigd"], "Hij sloeg een Egyptenaar die vocht met een man van zijn volk en doodde hem; hij had er meteen spijt van."),
"prophets_072": ("Wie waarschuwde Musa dat de leiders samenzwoeren om hem te doden?", ["Een man die van het andere eind van de stad kwam aangerend", "Zijn moeder", "Harun", "Een soldaat"], "«Een man kwam aangerend van het verste deel van de stad: zij beramen jouw dood, dus vertrek!»"),
"prophets_073": ("Wat deed Musa bij aankomst in Madyan voor twee vrouwen bij de drinkplaats?", ["Hij gaf hun kudde te drinken", "Hij verkocht hun een kameel", "Hij bouwde een huis voor hen", "Hij leerde hun lezen"], "Hij gaf hun kudde te drinken en trok zich daarna terug in de schaduw, Allah aanroepend."),
"prophets_074": ("Hoeveel jaar vroeg de oude man van Madyan Musa te werken om met zijn dochter te trouwen?", ["Acht, en tien als hij wilde", "Eén", "Veertig", "Drie"], "«Je zult mij acht jaar dienen; als je er tien voltooit, is dat uit eigen wil.»"),
"prophets_075": ("Wat gebood Allah Musa uit te doen in de heilige vallei Tuwa?", ["Zijn sandalen", "Zijn mantel", "Zijn staf", "Zijn tulband"], "«Doe je sandalen uit: je bent in de heilige vallei Tuwa.»"),
"prophets_076": ("Wat was het tweede teken dat Musa kreeg, na de staf?", ["Zijn hand kwam wit tevoorschijn, zonder kwaad", "Hij kon vliegen", "Zijn stem werd donder", "Hij zag 's nachts"], "«Druk je hand tegen je zij: zij zal wit tevoorschijn komen, zonder ziekte.»"),
"prophets_077": ("Wat vroeg Musa aan Allah voordat hij naar de Farao ging?", ["Zijn borst te verruimen en zijn tong los te maken", "Een leger", "Goud", "Een snel paard"], "«Mijn Heer, verruim mijn borst, maak mijn taak licht en maak de knoop in mijn tong los.»"),
"prophets_078": ("Wie vroeg Musa aan Allah als helper bij zijn missie?", ["Zijn broer Harun", "Zijn zoon", "Zijn schoonvader", "Een engel"], "«Stel voor mij een helper aan uit mijn familie: Harun, mijn broer.»"),
"prophets_079": ("Wat deden de tovenaars van de Farao toen de staf van Musa hun illusies verslond?", ["Zij vielen in neerwerping en geloofden", "Zij vluchtten", "Zij lachten", "Zij vielen Musa aan"], "De tovenaars wierpen zich neer: «Wij geloven in de Heer der werelden, de Heer van Musa en Harun.»"),
"prophets_080": ("Welke van deze plagen noemt de Koran onder die welke tegen het volk van de Farao werden gezonden?", ["Sprinkhanen", "Sneeuw", "Wolven", "Vuur"], "«Wij zonden over hen de vloed, sprinkhanen, luizen, kikkers en bloed.»"),
"prophets_081": ("Wat deed Allah volgens de Koran met het lichaam van de Farao nadat hij was verdronken?", ["Hij bewaarde het als teken", "Hij liet het verdwijnen", "Hij verbrandde het", "Hij gaf het terug aan zijn volk"], "«Vandaag zullen Wij jouw lichaam redden, opdat jij een teken bent voor wie na jou komen.»"),
"prophets_082": ("Wat vroeg de gelovige vrouw van de Farao volgens de Koran aan Allah?", ["Een huis dicht bij Hem in het Paradijs", "Een zoon", "De dood van de Farao", "Een koninkrijk"], "«Mijn Heer, bouw voor mij bij U een huis in het Paradijs, en red mij van de Farao.»"),
"prophets_083": ("Hoeveel nachten duurde de afspraak van Allah met Musa op de berg?", ["Veertig", "Zeven", "Tien", "Honderd"], "«Wij stelden voor Musa dertig nachten vast en vulden ze aan met tien: veertig nachten.»"),
"prophets_084": ("Wat gebeurde er toen Musa vroeg Allah te mogen zien?", ["Allah openbaarde Zich aan de berg, die verbrokkelde, en Musa viel bewusteloos neer", "Hij zag Allah", "Er gebeurde niets", "De berg steeg op naar de hemel"], "«Kijk naar de berg: als hij op zijn plaats blijft, zul je Mij zien.» De berg werd verpulverd en Musa viel bewusteloos neer."),
"prophets_085": ("Waarop schreef Allah vermaningen en uitleg voor Musa?", ["Op Tafelen", "Op palmbladeren", "Op een zwarte steen", "Op leer"], "«Wij schreven voor hem op de Tafelen een vermaning over alle dingen.»"),
"prophets_086": ("Wie maakte het kalf dat de Kinderen van Israël aanbaden terwijl Musa weg was?", ["As-Samiri", "Harun", "De Farao", "Qarun"], "«As-Samiri heeft hen misleid»: uit hun sieraden maakte hij een kalf dat een loeiend geluid maakte."),
"prophets_087": ("Hoeveel bronnen ontsprongen uit de rots waarop Musa met zijn staf sloeg?", ["Twaalf", "Zeven", "Drie", "Veertig"], "«Sla met je staf op de rots»: twaalf bronnen ontsprongen, één voor elke stam."),
"prophets_088": ("Welk voedsel zond Allah neer voor de Kinderen van Israël in de woestijn?", ["Manna en kwartels", "Rijst en vis", "Dadels en melk", "Brood en olijven"], "«Wij zonden manna en kwartels op jullie neer.»"),
"prophets_089": ("Welke kleur had de koe die Musa de Kinderen van Israël opdroeg te offeren?", ["Helder geel", "Zwart", "Wit", "Rood"], "«Het is een gele koe, helder van kleur, een genot voor wie haar zien.»"),
"prophets_090": ("Wie uit het volk van Musa werd met zijn huis door de aarde verzwolgen vanwege zijn hoogmoed en rijkdom?", ["Qarun", "Haman", "As-Samiri", "Jalut"], "Qarun bezat enorme schatten; «Wij lieten de aarde hem en zijn huis verzwelgen.»"),
"prophets_091": ("Welk metaal maakte Allah zacht voor Dawud?", ["IJzer", "Goud", "Koper", "Zilver"], "«En Wij maakten het ijzer buigzaam voor hem.»"),
"prophets_092": ("Wat leerde Allah Dawud te maken om mensen in de strijd te beschermen?", ["Maliënkolders", "Zwaarden", "Houten schilden", "Torens"], "«Wij leerden hem het maken van harnassen om jullie te beschermen.»"),
"prophets_093": ("Welke reus doodde Dawud volgens de Koran in de strijd?", ["Jalut (Goliath)", "De Farao", "Haman", "Nimrod"], "«En Dawud doodde Jalut, en Allah gaf hem het koningschap en de wijsheid.»"),
"prophets_094": ("Hoe stelde koning Talut zijn leger op de proef voordat hij Jalut tegemoet trad?", ["Een rivier: er niet uit drinken, behalve een handvol", "Een wedloop", "Een driedaagse vasten", "Een berg beklimmen"], "«Allah zal jullie beproeven met een rivier: wie eruit drinkt hoort niet bij mij, behalve wie een handvol schept.»"),
"prophets_095": ("Wat liet Allah samen met Dawud Hem verheerlijken?", ["De bergen en de vogels", "De winden", "De djinn", "De vissen"], "«En Wij maakten de bergen dienstbaar om Ons te verheerlijken, samen met Dawud, en de vogels.»"),
"prophets_096": ("Welk element maakte Allah dienstbaar aan Sulayman om hem te brengen waar hij wilde?", ["De wind", "Het vuur", "De regen", "De zee"], "«En aan Sulayman, de wind, krachtig waaiend op zijn bevel naar het gezegende land.»"),
"prophets_097": ("Welke vogel bracht Sulayman nieuws over het koninkrijk Saba?", ["De hop", "De adelaar", "De duif", "De raaf"], "De hop keerde terug en zei: «Ik heb iets vernomen wat jij niet weet, en ik breng je zeker nieuws uit Saba.»"),
"prophets_098": ("Welk klein schepsel waarschuwde zijn soortgenoten naar binnen te gaan toen het leger van Sulayman naderde?", ["Een mier", "Een bij", "Een muis", "Een spin"], "Een mier zei: «O mieren, ga jullie woningen binnen, opdat Sulayman en zijn soldaten jullie niet onbewust vertrappen.»"),
"prophets_099": ("Hoe snel werd de troon van de koningin van Saba naar Sulayman gebracht?", ["Voordat zijn blik naar hem terugkeerde", "In één dag", "In zeven dagen", "In een maand"], "Degene die kennis van het Boek had zei: «Ik breng hem naar je toe voordat je blik naar je terugkeert.»"),
"prophets_100": ("Wat maakten de djinn volgens de Koran voor Sulayman?", ["Heiligdommen, beelden en grote bekkens", "Vliegende tapijten", "Schepen", "Bergen"], "«Zij maakten voor hem wat hij wilde: hoge zalen, beelden, schalen als waterbekkens en vaststaande ketels.»"),
"prophets_101": ("Hoe kwamen de djinn de dood van Sulayman te weten?", ["Een schepsel van de aarde knaagde aan zijn staf en hij viel", "Een engel vertelde het hun", "De hop vertelde het hun", "Zij zagen hem sterven"], "Alleen het «schepsel van de aarde» dat aan zijn staf at onthulde zijn dood; de djinn beseften dat zij het onzichtbare niet kenden."),
"prophets_102": ("Welk bijzonder gebed richtte Sulayman tot Allah?", ["Een koninkrijk dat niemand na hem zou hebben", "Een lang leven", "De rijkdom van Qarun", "De macht om te vliegen"], "«Mijn Heer, vergeef mij en schenk mij een koninkrijk dat niemand na mij zal toebehoren.»"),
"prophets_103": ("Wat gebood Allah Ayyub te doen om zijn gezondheid terug te krijgen?", ["Met zijn voet op de grond stampen: er ontsprong een koele bron", "Een maand vasten", "Baden in de zee", "Een berg beklimmen"], "«Stamp met je voet: hier is een koele bron om je mee te wassen, en om te drinken.»"),
"prophets_104": ("Welke smeekbede deed Yunus in de duisternis van de buik van de vis?", ["«Er is geen god dan U! Glorie zij U, ik behoorde tot de onrechtvaardigen»", "«Mijn Heer, geef mij een koninkrijk»", "«Mijn Heer, zend mij regen»", "«Mijn Heer, laat mij U zien»"], "«Hij riep in de duisternis: er is geen god dan U! Verheven bent U; ik behoorde tot de onrechtvaardigen.»"),
"prophets_105": ("Welke plant liet Allah over Yunus groeien nadat de vis hem had uitgeworpen?", ["Een kalebasplant (yaqtin)", "Een palmboom", "Een olijfboom", "Een wijnstok"], "«En Wij lieten over hem een kalebasplant groeien.»"),
"prophets_106": ("Naar hoeveel mensen werd Yunus volgens de Koran gezonden?", ["Honderdduizend, of meer", "Duizend", "Tienduizend", "Twaalf"], "«En Wij zonden hem naar honderdduizend, of meer.»"),
"prophets_107": ("Welk teken gaf Allah Zakariyya ter bevestiging van de komst van zijn zoon?", ["Drie nachten niet tot de mensen spreken, hoewel gezond", "Een vallende ster", "Regen in de zomer", "Een droom"], "«Jouw teken is dat je drie nachten niet tot de mensen zult spreken, hoewel je gezond bent.»"),
"prophets_108": ("Wat zegt Allah over de naam Yahya?", ["Niemand vóór hem had die naam gekregen", "Het was de naam van zijn grootvader", "Zijn moeder koos hem", "Het was de naam van een koning"], "«Wij brengen jou het goede nieuws van een jongen wiens naam Yahya zal zijn; Wij hebben deze naam niet eerder aan iemand gegeven.»"),
"prophets_109": ("Wat schonk Allah Yahya toen hij nog een kind was?", ["Wijsheid", "Een koninkrijk", "Een paard", "Een schat"], "«O Yahya, neem het Boek met vastberadenheid.» En Wij gaven hem het oordeel toen hij nog een jongen was."),
"prophets_110": ("Wat had de moeder van Maryam beloofd voor het kind dat zij droeg?", ["Het toe te wijden aan de dienst van Allah", "Het naar Egypte te sturen", "Er een koning van te maken", "Het aan een herder toe te vertrouwen"], "«Mijn Heer, ik heb U beloofd wat in mijn schoot is, toegewijd aan Uw dienst.»"),
"prophets_111": ("Welke profeet nam de zorg voor Maryam op zich na haar geboorte?", ["Zakariyya", "Yahya", "Isa", "Dawud"], "«En Hij vertrouwde haar toe aan de zorg van Zakariyya», die bij haar voorzieningen van Allah aantrof."),
"prophets_112": ("Boven wie verkoos Allah Maryam volgens de Koran?", ["De vrouwen van de werelden", "De koninginnen", "De engelen", "De profeten"], "«O Maryam, Allah heeft jou uitverkoren en gezuiverd, en jou uitverkoren boven de vrouwen van de werelden.»"),
"prophets_113": ("Wat viel er voor Maryam toen zij aan de stam van de palmboom schudde?", ["Verse, rijpe dadels", "Olijven", "Vijgen", "Regen"], "«Schud de stam van de palmboom naar je toe: hij zal verse, rijpe dadels op je laten vallen.»"),
"prophets_114": ("Welk woord gebruikt de Koran voor Maryam in soera Al-Ma'ida?", ["Waarachtige (siddiqa)", "Koningin", "Profetes", "Strijdster"], "«De Messias, zoon van Maryam, was slechts een boodschapper… en zijn moeder was een waarachtige.»"),
"prophets_115": ("Welke titel geeft de Koran aan Isa, zoon van Maryam?", ["Al-Masih (de Messias)", "Al-Khalil", "Al-Kalim", "As-Siddiq"], "«Zijn naam zal zijn de Messias, Isa zoon van Maryam, aanzienlijk in deze wereld en in het Hiernamaals.»"),
"prophets_116": ("Wat vormde Isa uit klei, met Allahs toestemming?", ["De gedaante van een vogel, die levend werd", "Een huis", "Een standbeeld van een koning", "Een boot"], "«Ik vorm voor jullie uit klei de gedaante van een vogel, dan blaas ik erin en het wordt een vogel met Allahs toestemming.»"),
"prophets_117": ("Hoe heten de naaste metgezellen van Isa, die zich «Allahs helpers» verklaarden?", ["De Hawariyyun (de discipelen)", "De Ansar", "De Muhajirun", "De Sahaba"], "«De discipelen zeiden: wij zijn de helpers van Allah.»"),
"prophets_118": ("Wat vroegen de discipelen aan Isa, dat soera Al-Ma'ida haar naam gaf?", ["Een gedekte tafel met voedsel, neergezonden uit de hemel", "Een boek", "Een koninkrijk", "Goud"], "«Kan jouw Heer voor ons een gedekte tafel met voedsel uit de hemel neerzenden?»"),
"prophets_119": ("Wat zegt de Koran over het einde van de missie van Isa op aarde?", ["Hij werd niet gedood en niet gekruisigd: Allah verhief hem tot Zich", "Hij stierf van ouderdom", "Hij verdronk", "Hij ging naar Egypte"], "«Zij doodden hem niet, noch kruisigden zij hem… maar Allah verhief hem tot Zich.»"),
"prophets_120": ("Onder welke naam kondigde Isa een boodschapper aan die na hem zou komen?", ["Ahmad", "Yahya", "Musa", "Ilyas"], "«…het goede nieuws brengend van een boodschapper die na mij komt, wiens naam Ahmad is.»"),
"prophets_121": ("Om de aanbidding van welke afgod berispte de profeet Ilyas zijn volk?", ["Ba'l", "Hubal", "Al-Lat", "Wadd"], "«Roepen jullie Ba'l aan en verlaten jullie de beste der scheppers?»"),
"prophets_122": ("Welke drie profeten noemt de Koran samen «onder de geduldigen»?", ["Isma'il, Idris en Dhul-Kifl", "Nuh, Hud en Salih", "Musa, Harun en Yusha'", "Dawud, Sulayman en Ayyub"], "«En Isma'il, Idris en Dhul-Kifl: allen behoorden tot de geduldigen.»"),
"prophets_123": ("Welke profeet wordt in soera Sad naast Isma'il en Dhul-Kifl genoemd?", ["Al-Yasa' (Elisa)", "Yunus", "Lut", "Shu'ayb"], "«En gedenk Isma'il, Al-Yasa' en Dhul-Kifl: allen behoren tot de uitmuntenden.»"),
"prophets_124": ("Welke titel geeft de Koran de Profeet Muhammad ﷺ in vers 33:40?", ["Het Zegel der Profeten", "De Koning der Arabieren", "De Vader der gelovigen", "De Vriend van Allah"], "«Muhammad… is de Boodschapper van Allah en het Zegel der Profeten.»"),
"prophets_125": ("Als wat werd de Profeet Muhammad ﷺ volgens de Koran gezonden?", ["Een genade voor de werelden", "Een koning", "Een rechter", "Een krijger"], "«Wij hebben jou slechts gezonden als een genade voor de werelden.»"),
"prophets_126": ("Wat doen Allah en Zijn engelen volgens vers 33:56 voor de Profeet ﷺ?", ["Zij zenden zegeningen over hem", "Zij beschermen hem tegen de winden", "Zij zenden hem regen", "Zij kijken zwijgend naar hem"], "«Allah en Zijn engelen zenden zegeningen over de Profeet. O gelovigen, zend zegeningen over hem en groet hem met vrede.»"),
"prophets_127": ("Hoe beschrijft de Koran het karakter van de Profeet ﷺ in soera Al-Qalam?", ["«Jij hebt een verheven karakter»", "«Jij bent een grote koning»", "«Jij bent de rijkste»", "«Jij bent de sterkste»"], "«En voorwaar, jij hebt een verheven karakter.»"),
"prophets_128": ("Waaraan herinnert vers 3:144 ons over Muhammad ﷺ?", ["Hij is slechts een boodschapper, en vóór hem zijn boodschappers heengegaan", "Hij zal nooit sterven", "Hij is een engel", "Hij kent de toekomst"], "«Muhammad is slechts een boodschapper; vóór hem zijn boodschappers heengegaan.»"),
"prophets_129": ("Welke vijf profeten noemt vers 33:7 samen voor het plechtige verbond?", ["Nuh, Ibrahim, Musa, Isa en Muhammad ﷺ", "Adam, Nuh, Hud, Salih en Lut", "Dawud, Sulayman, Ayyub, Yunus en Idris", "Isma'il, Ishaq, Ya'qub, Yusuf en Musa"], "«Wij namen van de profeten hun verbond: van jou, van Nuh, Ibrahim, Musa en Isa zoon van Maryam.»"),
"prophets_130": ("Welk beroep oefende volgens een hadith in al-Bukhari elke profeet uit?", ["Herder", "Timmerman", "Smid", "Koopman"], "«Allah zond geen enkele profeet die geen schapen hoedde», en de Profeet ﷺ hoedde ze voor de mensen van Mekka."),
"prophets_131": ("Welke profeet werkte volgens een hadith in Muslim als timmerman?", ["Zakariyya", "Nuh", "Idris", "Yusuf"], "De Profeet ﷺ zei: «Zakariyya was een timmerman.»"),
"prophets_132": ("Van welke profeet zei de Profeet ﷺ dat hij «het dichtst bij hem stond» van alle mensen, in deze wereld en de volgende?", ["Isa zoon van Maryam", "Musa", "Ibrahim", "Nuh"], "«Ik sta van alle mensen het dichtst bij Isa zoon van Maryam in deze wereld en in het Hiernamaals; de profeten zijn broeders.»"),
"prophets_133": ("Hoeveel soera's van de Koran zijn naar een profeet genoemd?", ["Zes", "Twee", "Twaalf", "Vijfentwintig"], "Yunus (10), Hud (11), Yusuf (12), Ibrahim (14), Muhammad (47) en Nuh (71)."),
"prophets_134": ("Met welke drie woorden beschrijft de Koran Ibrahim in vers 11:75?", ["Zachtmoedig, teerhartig, steeds terugkerend tot Allah", "Rijk, machtig, geleerd", "Sterk, snel, dapper", "Koning, rechter, krijger"], "«Voorwaar, Ibrahim was zachtmoedig, meelevend en steeds terugkerend tot Allah.»"),
"prophets_135": ("Waarvoor berispte Shu'ayb zijn volk, naast de afgoderij?", ["Bedrog met maten en gewichten", "Niet bidden", "'s Nachts reizen", "Vis eten"], "«Geef volle maat en gewicht, en onthoud de mensen niet wat hun toekomt.»"),
"prophets_136": ("Wat trof het volk van Shu'ayb nadat het zijn boodschap had verworpen?", ["Een aardbeving", "Een zondvloed", "Een regen van vuur", "Een zwerm vogels"], "«Toen greep de aardbeving hen, en zij lagen in hun huizen als voorover gevallen lijken.»"),
"prophets_137": ("Welk nieuws gaven de engelen Ibrahim nadat zij zijn vrees hadden weggenomen?", ["Dat zij naar het volk van Lut waren gezonden", "Dat er een zondvloed kwam", "Dat de Ka'ba vernietigd zou worden", "Dat de Farao zou verdrinken"], "«Vrees niet: wij zijn gezonden naar het volk van Lut.»"),
"prophets_138": ("Wat vroeg Ibrahim voor zichzelf en zijn nageslacht in vers 14:40?", ["Onderhouders van het gebed te zijn", "Koningen te zijn", "Rijk te zijn", "Lang te leven"], "«Mijn Heer, maak mij een onderhouder van het gebed, en ook uit mijn nageslacht.»"),
"prophets_139": ("Wie liet Yusuf aan het einde van zijn verhaal op de troon plaatsnemen, voordat allen zich voor hem bogen?", ["Zijn ouders", "De koning", "Zijn broers", "Zijn zoon"], "«Hij liet zijn ouders op de troon plaatsnemen, en zij wierpen zich voor hem neer»: de kinderdroom kwam uit."),
"prophets_140": ("Waarom wilden de broers van Yusuf van hem af?", ["Uit jaloezie: hun vader hield meer van hem", "Hij had gestolen", "Hij weigerde te werken", "Hij was ziek"], "«Yusuf en zijn broer zijn onze vader dierbaarder dan wij… Dood Yusuf of verban hem naar een of ander land.»"),
"prophets_141": ("Wat brachten de broers van Yusuf hun vader om hem te laten geloven dat een wolf hem had opgegeten?", ["Zijn hemd met vals bloed bevlekt", "Zijn sandalen", "Zijn staf", "Een wolventand"], "«Zij brachten zijn hemd met vals bloed erop»; Ya'qub antwoordde: «Geduld is het meest passend.»"),
"prophets_142": ("Wat beloofde Allah de moeder van Musa toen Hij haar inspireerde hem in de rivier te leggen?", ["Hem aan haar terug te geven en hem tot boodschapper te maken", "Haar een andere zoon te geven", "Haar koningin te maken", "Regen te zenden"], "«Vrees niet en treur niet: Wij zullen hem aan jou teruggeven en hem tot een van de boodschappers maken.»"),
"prophets_143": ("Waarmee sloeg Musa op de zee zodat zij spleet?", ["Met zijn staf", "Met zijn hand", "Met een steen", "Met zijn zwaard"], "«Sla met je staf op de zee»: zij spleet, en elke kant was als een geweldige berg."),
"prophets_144": ("Wat was het eerste dat Allah tegen Musa zei toen Hij hem aansprak?", ["«Ik ben Allah, er is geen god dan Ik: aanbid Mij en verricht het gebed»", "«Ga vissen»", "«Bouw een ark»", "«Ga terug naar de Farao»"], "«Voorwaar, Ik ben Allah; er is geen god dan Ik, aanbid Mij dus en verricht het gebed ter gedachtenis aan Mij.»"),
"prophets_145": ("Hoe zei Allah Musa en Harun tot de Farao te spreken?", ["Met zachte woorden", "Met woede", "Schreeuwend", "In stilte"], "«Ga naar de Farao… en spreek tot hem met zachte woorden; misschien laat hij zich vermanen of vreest hij.»"),
"prophets_146": ("Wat zei Musa tegen zijn jonge dienaar aan het begin van zijn reis naar de samenvloeiing van de twee zeeën?", ["Dat hij niet zou stoppen voordat hij de samenvloeiing van de twee zeeën had bereikt", "Dat hij naar huis wilde", "Dat hij bang was", "Dat hij goud zocht"], "«Ik zal niet opgeven voordat ik de samenvloeiing van de twee zeeën heb bereikt, al moet ik jaren doorgaan.»"),
"prophets_147": ("Wat deed de wijze dienaar in het bijzijn van Musa, die het toen niet begreep?", ["Hij maakte een gat in een boot", "Hij bouwde een brug", "Hij stak een vuur aan", "Hij plantte een boom"], "Hij doorboorde de boot, doodde daarna een jongen, en zette een muur recht, en legde Musa naderhand elke daad uit."),
"prophets_148": ("Wat waren de eerste woorden van Isa, nog in de wieg?", ["«Ik ben de dienaar van Allah; Hij gaf mij het Boek en maakte mij tot profeet»", "«Ik ben de zoon van God»", "«Ik ben een koning»", "«Ik heb honger»"], "«Hij zei: voorwaar, ik ben de dienaar van Allah. Hij heeft mij het Boek gegeven en mij tot profeet gemaakt.»"),
"prophets_149": ("Wat zeiden Adam en zijn vrouw tegen Allah nadat zij van de boom hadden gegeten?", ["«Onze Heer, wij hebben onszelf onrecht aangedaan; als U ons niet vergeeft, zijn wij verloren»", "«Het was niet onze schuld»", "«Het was de schuld van de boom»", "Zij zeiden niets"], "«Onze Heer, wij hebben onszelf onrecht aangedaan, en als U ons niet vergeeft en ons niet genadig bent, behoren wij zeker tot de verliezers.»"),
"prophets_150": ("Welke missie gaf Allah Nuh ten aanzien van zijn volk, in het eerste vers van soera Nuh?", ["Hen waarschuwen voordat een pijnlijke straf hen zou treffen", "Een stad bouwen", "Hun leren vissen", "Hen tot koningen maken"], "«Wij zonden Nuh naar zijn volk: waarschuw jouw volk voordat een pijnlijke straf hen treft.»"),
}
